CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 INT COLLATE NOCASE, c1 REAL COLLATE NOCASE, c2 INTEGER UNIQUE, c3 TEXT CHECK(c3 IS NULL OR length(c3) < 40), c4 BLOB DEFAULT 'd');
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(x'', NULL, 3, NULL, 1e-7);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(x'b2', NULL, x'9cbd3a8f3bb5', x'3d85', 'beta');
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES('Lambda', 5, 'theta', NULL, '1e3');
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(2.5, NULL, -664, 'alpha', NULL);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 ANY DEFAULT 'd', c1 REAL CHECK(c1 IS NULL OR length(c1) < 40), c2 INTEGER CHECK(c2 IS NULL OR length(c2) < 40), ref INTEGER REFERENCES t0(id)) STRICT;
INSERT OR IGNORE INTO t1(c0, c1, c2, ref) VALUES(0.1, 21.687, 354, 3);
INSERT OR IGNORE INTO t1(c0, c1, c2, ref) VALUES(123456789012, -380, 869, 7);
INSERT OR IGNORE INTO t1(c0, c1, c2, ref) VALUES(x'3e', 4.816, -303, 7);
INSERT OR IGNORE INTO t1(c0, c1, c2, ref) VALUES(-5, -9.668, 22, 4);
SELECT length(' pad '), upper(' pad '), lower(' pad '), substr(' pad ', 3, 5), instr(' pad ', '42'), replace(' pad ', '', ''), trim(' pad '), ltrim(' pad ', 'ab'), hex(' pad '), quote(' pad '), unicode(' pad '), ' pad ' LIKE '%a_', ' pad ' GLOB 'a*', char(82, 329), ' pad ' || '42', ' pad ' < '42', ' pad ' = '42' COLLATE NOCASE;
SELECT length('x_y'), upper('x_y'), lower('x_y'), substr('x_y', -2, 4), instr('x_y', 'nu'), replace('x_y', 'é', '_'), trim('x_y'), ltrim('x_y', 'ab'), hex('x_y'), quote('x_y'), unicode('x_y'), 'x_y' LIKE 'a%', 'x_y' GLOB '?', char(86, 205), 'x_y' || 'nu', 'x_y' < 'nu', 'x_y' = 'nu' COLLATE NOCASE;
SELECT length('tau'), upper('tau'), lower('tau'), substr('tau', 3, 3), instr('tau', 'iota'), replace('tau', 'e', '_'), trim('tau'), ltrim('tau', 'ab'), hex('tau'), quote('tau'), unicode('tau'), 'tau' LIKE '%é%', 'tau' GLOB '*', char(73, 202), 'tau' || 'iota', 'tau' < 'iota', 'tau' = 'iota' COLLATE NOCASE;
SELECT length('chi'), upper('chi'), lower('chi'), substr('chi', 4, 2), instr('chi', '-7'), replace('chi', 'a', ''), trim('chi'), ltrim('chi', 'ab'), hex('chi'), quote('chi'), unicode('chi'), 'chi' LIKE '_', 'chi' GLOB '*', char(81, 761), 'chi' || '-7', 'chi' < '-7', 'chi' = '-7' COLLATE NOCASE;
SELECT length('xi'), upper('xi'), lower('xi'), substr('xi', -1, 1), instr('xi', 'Ελλάδα'), replace('xi', '', '_'), trim('xi'), ltrim('xi', 'ab'), hex('xi'), quote('xi'), unicode('xi'), 'xi' LIKE '%a_', 'xi' GLOB 'a*', char(85, 284), 'xi' || 'Ελλάδα', 'xi' < 'Ελλάδα', 'xi' = 'Ελλάδα' COLLATE NOCASE;
SELECT length('Ελλάδα'), upper('Ελλάδα'), lower('Ελλάδα'), substr('Ελλάδα', 2, 5), instr('Ελλάδα', 'tau'), replace('Ελλάδα', 'é', 'XY'), trim('Ελλάδα'), ltrim('Ελλάδα', 'ab'), hex('Ελλάδα'), quote('Ελλάδα'), unicode('Ελλάδα'), 'Ελλάδα' LIKE 'A%', 'Ελλάδα' GLOB '*', char(77, 479), 'Ελλάδα' || 'tau', 'Ελλάδα' < 'tau', 'Ελλάδα' = 'tau' COLLATE NOCASE;
SELECT count(*), count(ref), sum(ref), total(ref), avg(ref), min(ref), max(ref), count(DISTINCT ref) FROM t1 WHERE NOT coalesce('naïve', ref);
SELECT ref, count(*), group_concat(id) FROM (SELECT * FROM t1 ORDER BY id) GROUP BY ref ORDER BY ref;
